mapper.select:
SELECT

FROM wf_email_template a
WHERE a.del_flag = '0'

	and  a.ID =#{id}


	and  a.TENANT_ID =#{tenantId}


	and  a.TEMP_STATUS =#{tempStatus}


	and  a.TEMP_NAME  like #{tempName}


	and  a.TEMP_TAG  like #{tempTag}

mapper.delete:
delete from wf_email_template where
id in

	#{id}
